mapper.update:
update beverage
set is_deleted = 1,
update_time = #{date}
where id = #{beverageId}

update beverage
set stock = #{stock},
update_time = #{date}
where id = #{id}

update beverage
set stock = stock - #{quantity},
update_time = #{date}
where id = #{id}
  and stock >= #{quantity}
  and status = 1
  and is_deleted = 0
